const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const loader=document.querySelector('.loader');
setTimeout(()=>loader?.classList.add('hidden'),reducedMotion?0:700);
if('IntersectionObserver' in window){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.07});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('#main-nav');
const closeMenu=()=>{nav?.classList.remove('open');menuButton?.setAttribute('aria-expanded','false');menuButton?.setAttribute('aria-label','Abrir menú');if(menuButton)menuButton.textContent='☰'};
menuButton?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');menuButton.textContent=open?'×':'☰'});
document.querySelectorAll('.nav-group').forEach(group=>group.addEventListener('toggle',()=>{if(group.open)document.querySelectorAll('.nav-group').forEach(other=>{if(other!==group)other.open=false})}));
document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))document.querySelectorAll('.nav-group').forEach(g=>g.open=false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const opened=document.querySelector('.nav-group[open]');if(opened){opened.open=false;opened.querySelector('summary').focus()}else if(nav?.classList.contains('open')){closeMenu();menuButton.focus()}}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-category]').forEach(f=>f.hidden=button.dataset.filter!=='all'&&f.dataset.category!==button.dataset.filter)}));
const lightbox=document.querySelector('.lightbox');
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{lightbox.querySelector('img').src=button.dataset.photo;lightbox.querySelector('img').alt=button.dataset.caption;lightbox.querySelector('p').textContent=button.dataset.caption;lightbox.showModal()}));lightbox?.querySelector('button').addEventListener('click',()=>lightbox.close());lightbox?.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
const topButton=document.querySelector('.back-top');window.addEventListener('scroll',()=>topButton?.classList.toggle('show',window.scrollY>650),{passive:true});topButton?.addEventListener('click',()=>window.scrollTo({top:0,behavior:reducedMotion?'instant':'smooth'}));
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const inquiryLabels={nombre:'Nombre',telefono:'Teléfono',correo:'Correo',ubicacion:'Ubicación',superficie:'Superficie',inversion:'Inversión prevista',terreno:'Terreno',estilo:'Estilo',mensaje:'Consulta'};
document.querySelectorAll('[data-inquiry]').forEach(form=>{let prepared='';const result=form.querySelector('.inquiry-result');form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const lines=Object.entries(inquiryLabels).map(([key,label])=>{const value=String(data.get(key)||'').trim();return value?`${label}: ${value}`:''}).filter(Boolean);prepared=`Hola, Romerito Construcción. Quisiera ${form.dataset.inquiry==='presupuesto'?'solicitar una cotización para mi casa':'consultar sobre un proyecto'}.\n\n${lines.join('\n')}\n\nQuedo a la espera de una propuesta según las características del proyecto.`;result.querySelector('pre').textContent=prepared;result.querySelector('.send-inquiry').href='https://wa.me/51903301036?text='+encodeURIComponent(prepared);result.hidden=false;result.scrollIntoView({behavior:reducedMotion?'instant':'smooth',block:'nearest'})});form.addEventListener('input',()=>{result.hidden=true});form.querySelector('.download-inquiry').addEventListener('click',()=>{if(prepared)downloadText('SOLICITUD DE INFORMACIÓN · ROMERITO CONSTRUCCIÓN\n\n'+prepared+'\n\nEste resumen no es un presupuesto ni una oferta contractual.','solicitud-romerito.txt')})});
const configForm=document.querySelector('#config-form');
if(configForm){const images={Moderno:22,'Rústico':17,Campo:31};const preset=new URLSearchParams(location.search).get('estilo');if(Object.hasOwn(images,preset)){const input=Array.from(configForm.querySelectorAll('[name=estilo]')).find(el=>el.value===preset);if(input)input.checked=true}let summaryText='';const renderConfig=()=>{const data=new FormData(configForm);const style=data.get('estilo');const area=data.get('area');document.querySelector('#area-value').textContent=area+' m²';const img=document.querySelector('#config-image');img.src=`assets/obra-${images[style]}.jpeg`;img.alt='Referencia del estilo '+style;const extras=data.getAll('extras').join(', ')||'Por definir';const rows=[['Estilo',style],['Superficie',area+' m²'],['Dormitorios',data.get('dormitorios')],['Baños',data.get('banos')],['Extras',extras],['Terreno',data.get('terreno')],['Ubicación',String(data.get('ubicacion')).trim()||'Por definir']];const list=document.querySelector('#config-details');list.replaceChildren();rows.forEach(([label,value])=>{const row=document.createElement('div');const dt=document.createElement('dt');const dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);list.append(row)});summaryText='MI PROYECTO · ROMERITO CONSTRUCCIÓN\n\n'+rows.map(([k,v])=>`${k}: ${v}`).join('\n');const notes=String(data.get('notas')||'').trim();if(notes)summaryText+='\nDetalles: '+notes;summaryText+='\n\nPreferencias iniciales sujetas a revisión técnica. Solicito una cotización personalizada. El precio, alcance y plazo se confirman con Romerito.';document.querySelector('#config-send').href='https://wa.me/51903301036?text='+encodeURIComponent('Hola, quisiera consultar sobre esta idea para mi casa:\n\n'+summaryText)};configForm.addEventListener('input',renderConfig);configForm.addEventListener('change',renderConfig);configForm.addEventListener('submit',e=>e.preventDefault());document.querySelector('#config-download').addEventListener('click',()=>downloadText(summaryText,'mi-proyecto-romerito.txt'));renderConfig()}
